CREATE TABLE IF NOT EXISTS public."tmudmap" (
    "mudMapId"                   INT GENERATED BY DEFAULT AS IDENTITY,
    "eventId"                    INT NOT NULL DEFAULT 1,
    "country"                    VARCHAR(10) NOT NULL DEFAULT 'AU',
    "pageId"                     INT NOT NULL,
    "positionId"                 INT NOT NULL,
    "offerId"                    INT,
    "offerNumber"                INT,
    "offerName"                  VARCHAR(255),
    "offerType"                  VARCHAR(100),
    "brand"                      VARCHAR(100),
    "everydayPrice"              NUMERIC(19, 5),
    "advertisedPrice"            NUMERIC(19, 5),
    "saveValue"                  NUMERIC(19, 5),
    "savePercent"                NUMERIC(19, 5),
    "isReserved"                 BOOLEAN NOT NULL DEFAULT FALSE,
    "clearance"                  BOOLEAN DEFAULT FALSE,
    "new"                        BOOLEAN DEFAULT FALSE,
    "loyalty"                    BOOLEAN DEFAULT FALSE,
    "isActive"                   BOOLEAN NOT NULL DEFAULT TRUE,
    "userName"                   VARCHAR(100),
    "updatedAt"                  TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT pk_tmudmap PRIMARY KEY ("pageId", "positionId")
);

CREATE INDEX IF NOT EXISTS idx_tmudmap_offerId ON public."tmudmap" ("offerId");
CREATE INDEX IF NOT EXISTS idx_tmudmap_event_page_pos ON public."tmudmap" ("eventId", "pageId", "positionId");
